CREATE TABLE payment_link(id uuid PRIMARY KEY,merchant_id uuid NOT NULL REFERENCES merchant(id),token_digest char(64) NOT NULL UNIQUE,amount_minor bigint NOT NULL CHECK(amount_minor BETWEEN 100 AND 100000000),capture_mode varchar(20) NOT NULL CHECK(capture_mode IN('AUTOMATIC','MANUAL')),expires_at timestamptz NOT NULL,consumed_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment(id uuid PRIMARY KEY,merchant_id uuid NOT NULL REFERENCES merchant(id),link_id uuid UNIQUE REFERENCES payment_link(id),status varchar(20) NOT NULL DEFAULT 'PROCESSING',capture_mode varchar(20) NOT NULL,authorized_minor bigint NOT NULL DEFAULT 0,captured_minor bigint NOT NULL DEFAULT 0,refunded_minor bigint NOT NULL DEFAULT 0,reserved_refund_minor bigint NOT NULL DEFAULT 0,disputed_minor bigint NOT NULL DEFAULT 0,customer_name varchar(100) NOT NULL,authorization_expires_at timestamptz,provider_version bigint NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),CHECK(captured_minor>=0 AND refunded_minor>=0 AND reserved_refund_minor>=0 AND disputed_minor>=0),CHECK(refunded_minor+reserved_refund_minor+disputed_minor<=captured_minor));
CREATE TABLE checkout_session(id uuid PRIMARY KEY,link_id uuid NOT NULL REFERENCES payment_link(id),secret_digest char(64) NOT NULL,attempt_key varchar(128) NOT NULL,fingerprint char(64),payment_id uuid REFERENCES payment(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(link_id,secret_digest));
CREATE TABLE refund_reservation(id uuid PRIMARY KEY,operation_id uuid UNIQUE NOT NULL REFERENCES operation(id),payment_id uuid NOT NULL REFERENCES payment(id),merchant_id uuid NOT NULL REFERENCES merchant(id),amount_minor bigint NOT NULL CHECK(amount_minor>0),state varchar(20) NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounting_period(merchant_id uuid NOT NULL REFERENCES merchant(id),month date NOT NULL,status varchar(30) NOT NULL DEFAULT 'OPEN',version bigint NOT NULL DEFAULT 0,CHECK(EXTRACT(DAY FROM month)=1),PRIMARY KEY(merchant_id,month));
CREATE TABLE economic_source(id uuid PRIMARY KEY,merchant_id uuid NOT NULL REFERENCES merchant(id),provider_source_id varchar(128) NOT NULL,event_type varchar(40) NOT NULL,amount_minor bigint NOT NULL,occurred_at timestamptz NOT NULL,batch_id varchar(128),resource_id uuid NOT NULL,recognized boolean NOT NULL DEFAULT true,posting_month date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(merchant_id,provider_source_id,event_type),FOREIGN KEY(merchant_id,posting_month) REFERENCES accounting_period(merchant_id,month),CHECK(event_type IN('CAPTURE','FEE','REFUND','DISPUTE_OPEN','DISPUTE_WON','CORRECTION_CREDIT','CORRECTION_DEBIT','PAYOUT','SETTLEMENT','BATCH_ZERO')),CHECK((event_type IN('CAPTURE','DISPUTE_WON','CORRECTION_CREDIT') AND amount_minor>0) OR (event_type IN('FEE','REFUND','DISPUTE_OPEN','CORRECTION_DEBIT','PAYOUT') AND amount_minor<0) OR (event_type='SETTLEMENT' AND amount_minor<>0) OR (event_type='BATCH_ZERO' AND amount_minor=0)));
CREATE TABLE journal(id uuid PRIMARY KEY,merchant_id uuid NOT NULL REFERENCES merchant(id),source_id uuid NOT NULL REFERENCES economic_source(id),purpose varchar(40) NOT NULL,sequence bigint NOT NULL,period_month date NOT NULL,currency char(3) NOT NULL DEFAULT 'USD' CHECK(currency='USD'),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,purpose),UNIQUE(merchant_id,sequence),FOREIGN KEY(merchant_id,period_month) REFERENCES accounting_period(merchant_id,month));
CREATE TABLE ledger_entry(id uuid PRIMARY KEY,journal_id uuid NOT NULL REFERENCES journal(id),merchant_id uuid NOT NULL REFERENCES merchant(id),account varchar(40) NOT NULL CHECK(account IN('processor_clearing','merchant_payable','bank_control','adjustment_suspense')),debit bigint NOT NULL DEFAULT 0,credit bigint NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'USD' CHECK(currency='USD'),CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)));
CREATE INDEX ledger_scope ON ledger_entry(merchant_id,account);
CREATE FUNCTION check_journal() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE jid uuid; j journal%ROWTYPE; s economic_source%ROWTYPE; n bigint; d numeric; c numeric; da text; ca text;
BEGIN
 IF TG_TABLE_NAME='journal' THEN jid:=NEW.id; ELSE jid:=NEW.journal_id; END IF;
 SELECT * INTO j FROM journal WHERE id=jid; IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO s FROM economic_source WHERE id=j.source_id;
 IF s.merchant_id<>j.merchant_id OR s.posting_month<>j.period_month OR NOT s.recognized THEN RAISE EXCEPTION 'Journal source scope or recognition mismatch' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM accounting_period WHERE merchant_id=j.merchant_id AND month=j.period_month AND status IN('CLOSED','REOPEN_PROPOSED')) THEN RAISE EXCEPTION 'Posting period is closed' USING ERRCODE='23514'; END IF;
 SELECT count(*),sum(debit::numeric),sum(credit::numeric) INTO n,d,c FROM ledger_entry WHERE journal_id=jid;
 IF n<2 OR d<>c OR d IS NULL OR d<=0 OR d>9223372036854775807 THEN RAISE EXCEPTION 'Unbalanced journal' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM ledger_entry WHERE journal_id=jid AND (merchant_id<>j.merchant_id OR currency<>j.currency)) THEN RAISE EXCEPTION 'Entry scope mismatch' USING ERRCODE='23514'; END IF;
 CASE s.event_type WHEN 'CAPTURE','DISPUTE_WON','CORRECTION_CREDIT' THEN da:='processor_clearing';ca:='merchant_payable'; WHEN 'FEE','REFUND','DISPUTE_OPEN','CORRECTION_DEBIT' THEN da:='merchant_payable';ca:='processor_clearing'; WHEN 'PAYOUT' THEN da:='merchant_payable';ca:='bank_control'; WHEN 'SETTLEMENT' THEN IF s.amount_minor>0 THEN da:='bank_control';ca:='processor_clearing';ELSE da:='processor_clearing';ca:='bank_control';END IF; ELSE RAISE EXCEPTION 'Unsupported journal economic event'; END CASE;
 IF EXISTS(SELECT 1 FROM ledger_entry WHERE journal_id=jid AND ((debit>0 AND account<>da) OR (credit>0 AND account<>ca))) THEN RAISE EXCEPTION 'Economic account mapping mismatch' USING ERRCODE='23514'; END IF;
 IF d<>abs(s.amount_minor::numeric) THEN RAISE EXCEPTION 'Journal does not equal source' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER journal_balanced AFTER INSERT ON journal DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_journal();
CREATE CONSTRAINT TRIGGER entry_balanced AFTER INSERT ON ledger_entry DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_journal();
CREATE TRIGGER journal_immutable BEFORE UPDATE OR DELETE ON journal FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER entry_immutable BEFORE UPDATE OR DELETE ON ledger_entry FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE FUNCTION source_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR (NEW.id,NEW.merchant_id,NEW.provider_source_id,NEW.event_type,NEW.amount_minor,NEW.occurred_at,NEW.resource_id,NEW.posting_month) IS DISTINCT FROM (OLD.id,OLD.merchant_id,OLD.provider_source_id,OLD.event_type,OLD.amount_minor,OLD.occurred_at,OLD.resource_id,OLD.posting_month) OR (OLD.batch_id IS NOT NULL AND NEW.batch_id IS DISTINCT FROM OLD.batch_id) OR (OLD.recognized AND NOT NEW.recognized) THEN RAISE EXCEPTION 'Immutable source identity'; END IF; RETURN NEW; END $$;
CREATE TRIGGER source_identity BEFORE UPDATE OR DELETE ON economic_source FOR EACH ROW EXECUTE FUNCTION source_guard();
